// the door. Filing bookshelves run along the north and east walls, barrels as drawers along the west wall, a red rug
// on the south floor, and a lectern at the south end. Light: a lantern and a lit candle on the desk, a lantern on a
// barrel, a lantern on a post at the south-east corner. Lanes: the door cell x9 z16 and the x7..9 band stay clear.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const legend = {
  "B": "bookshelf", // filing shelves
  "f": ["dark_oak_fence", {}], // desk posts and the lamp post
  "S": ["dark_oak_slab", { type: "top" }], // desk top (bottom half under it: type bottom)
  "h": ["dark_oak_stairs", { facing: "east", half: "bottom" }], // clerk's chair, back to the east, facing the desk
  "k": ["barrel", { facing: "up" }], // filing drawers
  "p": "flower_pot", // on the shelves
  "r": "red_carpet", // rug
  "l": ["lectern", { facing: "east", has_book: "true" }], // the reading stand at the south end
  "L": ["lantern", { hanging: "false" }], // standing lanterns on a block
  "c": ["candle", { candles: "2", lit: "true" }], // desk candles
};

export function build(g) {
  const origin = [5, 4, 11];
  // y4: floor-level furniture. Rows run along +x (x5..x9), successive rows along +z (z11..z25). ' ' = the chimney, left alone.
  const floor = [
    "BBBBB", // z11 filing along the north wall
    "..fBB", // z12 desk post at x7; shelves on the east wall
    "...hB", // z13 chair at x8 facing the desk
    "..f..", // z14 desk post at x7
    ".....", // z15
    ".....", // z16 the door lane, kept clear
    "  ...", // z17 the fireplace's floor (chimney cells at x5..6)
    "  ...", // z18
    "k....", // z19 barrel drawers on the west wall
    "k....", // z20
    "k.rr.", // z21 barrel; the rug starts
    "..rr.", // z22
    "..rr.", // z23
    "..l.f", // z24 lectern at x7; lamp post at x9
    ".....", // z25
  ];
  // y5: the desk top, shelf pots, a lantern on the barrel and one on the post
  const top = [
    ".p.p.", // z11 pots on two shelves
    "..S..", // z12 desk top
    "..S..", // z13 desk top under the lantern
    "..S..", // z14 desk top
    ".....", "....." , ".....", ".....", ".....", ".....", // z15..z20
    "L....", // z21 lantern on the barrel
    ".....", ".....", ".....", // z22..z24
  ];
  // y5 lamp on the post at z24 x9
  top[13] = "....L";
  // y6: things standing on the desk
  const high = [
    "", "", "", "", "", "", "", "", "", "", "", "", "", "", "",
  ];
  high[1] = "..c..";  // z12 candle on the desk top
  high[2] = "..L..";  // z13 lantern on the desk top
  return layers(g, origin, legend, [floor, top, high]);
}

